# partition_by :: [1, 2, 3, 4, 5]
def partition_by(xs, pred):
    yes, no = [], []
    for x in xs:
        (yes if pred(x) else no).append(x)
    return yes, no

if __name__ == '__main__':
    print(partition_by([1, 2, 3, 4, 5]))

